/* Questions before joining (round 32), run after part 81. A community's owner or admins write up to eight questions people answer when they join (a short answer, a paragraph, one choice, several choices or an email address, each required or not), kept in the new server only table `community_join_forms`, one row per community; what each person answered is kept in the new server only table `community_join_answers`, one row per community and person, with the words of each question as it was asked, so a question changed later does not change an answer already given. The join flow shows the questions, a request waits with its answers for an admin in Requests, and the answers can be downloaded. No existing row changes. Until it runs, joining asks nothing new and Settings shows that the questions need this part. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_join_forms (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, questions jsonb NOT NULL DEFAULT '[]'::jsonb, updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_join_forms_pkey PRIMARY KEY (community_id), CONSTRAINT community_join_forms_questions_check CHECK (jsonb_typeof(questions) = 'array' AND jsonb_array_length(questions) <= 8 AND pg_column_size(questions) <= 32768));
ALTER TABLE public.community_join_forms ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_join_forms FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_join_forms TO service_role;
CREATE TABLE IF NOT EXISTS public.community_join_answers (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, answers jsonb NOT NULL DEFAULT '[]'::jsonb, submitted_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_join_answers_pkey PRIMARY KEY (community_id, user_id), CONSTRAINT community_join_answers_check CHECK (jsonb_typeof(answers) = 'array' AND jsonb_array_length(answers) <= 8 AND pg_column_size(answers) <= 65536));
CREATE INDEX IF NOT EXISTS community_join_answers_submitted_idx ON public.community_join_answers (community_id, submitted_at DESC);
ALTER TABLE public.community_join_answers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_join_answers FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_join_answers TO service_role;
notify pgrst, 'reload schema';
